import {spawnSync} from 'node:child_process';
const instance=process.argv[2];const sleep=ms=>new Promise(r=>setTimeout(r,ms));
function call(args){const p=spawnSync(process.execPath,['tools/godot-cli/dist/src/index.js',...args,'--project','.','--instance',instance,'--json'],{encoding:'utf8',maxBuffer:64*1024*1024});if(p.status!==0)throw Error((p.stdout+p.stderr).slice(0,1500));return JSON.parse(p.stdout).data;}
const action=(name,payload={})=>call(['runtime','action','--name',name,'--payload',JSON.stringify(payload)]).result;
const store=()=>call(['runtime','inspect','--store-only']).store;
action('debug_console',{run:'invincible on',open:false});action('settings_open_testing');action('settings_preview_stream',{moment:'alerts'});await sleep(450);let s=store().roguelite.stream.overlay;if(s.newFollowerReceipt!=='NEW FOLLOWER: pixelPilot followed'||s.subscriptionReceipt)throw Error('follower presentation missing '+JSON.stringify(s));console.log(s.newFollowerReceipt);if(instance.includes('render'))call(['game','capture','--output','artifacts/new-follower-cheap.png']);const end=Date.now()+4500;let sub=false;while(Date.now()<end){s=store().roguelite.stream.overlay;if(s.subscriptionReceipt.startsWith('NEW SUBSCRIBER: byteBuddy')){sub=true;break;}await sleep(120);}if(!sub||s.newFollowerReceipt)throw Error('queue handoff failed');console.log(s.subscriptionReceipt);await sleep(3500);s=store().roguelite.stream.overlay;if(!s.subscriptionReceipt.startsWith('GIFT SUB: cacheQueen')||s.newFollowerReceipt)throw Error('gift handoff failed '+JSON.stringify(s));console.log(s.subscriptionReceipt);console.log('FOLLOWER_REVEAL_OK');
